final class LifeMinistryReportManager {
    private static final Locale ES=new Locale("es","MX");
    private final Context context;private final MinisterioDb db;private final SharedPreferences colors;private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);
    LifeMinistryReportManager(Context context,MinisterioDb db){this.context=context;this.db=db;colors=context.getSharedPreferences("palette",Context.MODE_PRIVATE);}
    private int color(String key,String fallback){try{return Color.parseColor(colors.getString(key,fallback));}catch(Exception ignored){return Color.parseColor(fallback);}}
    private File output(String name){File dir=new File(context.getCacheDir(),"reportes");if(!dir.exists())dir.mkdirs();return new File(dir,name.replaceAll("[^A-Za-z0-9._-]","_"));}

    File monthlyPdf(String month)throws IOException{
        List<Models.LifePart> parts=db.lifeParts(month);Map<Long,Models.LifeProgramRow> assigned=assigned(month);Map<String,List<Models.LifePart>> byDate=new LinkedHashMap<>();for(Models.Meeting meeting:db.meetings(month))byDate.put(meeting.date,new ArrayList<>());for(Models.LifePart part:parts)byDate.computeIfAbsent(part.date,k->new ArrayList<>()).add(part);if(byDate.isEmpty())throw new IllegalArgumentException("No hay semanas configuradas para el mes seleccionado.");
        PdfDocument pdf=new PdfDocument();PdfDocument.Page page=pdf.startPage(new PdfDocument.PageInfo.Builder(792,612,1).create());Canvas canvas=page.getCanvas();canvas.drawColor(Color.WHITE);float y=0;box(canvas,0,y,792,32,color("title","#00B050"));text(canvas,"PROGRAMA VIDA Y MINISTERIO",396,y+22,14,Color.WHITE,true,Paint.Align.CENTER);y+=32;
        int rows=0;for(Map.Entry<String,List<Models.LifePart>> entry:byDate.entrySet()){Models.Meeting meeting=db.meeting(entry.getKey());rows+=meeting.suspended?1:Math.max(1,entry.getValue().size())+(meeting.visit?1:0);}float header=17f;float rowH=Math.max(8.5f,Math.min(36f,(612-y-byDate.size()*header*2-2)/Math.max(1,rows)));
        for(Map.Entry<String,List<Models.LifePart>> entry:byDate.entrySet()){Models.Meeting meeting=db.meeting(entry.getKey());Models.President president=db.president(meeting.presidentId);box(canvas,0,y,792,header,color("date","#0D6EFD"));fit(canvas,humanDate(entry.getKey())+(president==null?"":" · Presidente: "+president.name),396,y+header*.72f,780,9.5f,Color.WHITE,true);y+=header;headers(canvas,y,header);y+=header;if(meeting.suspended){box(canvas,0,y,792,rowH,color("title","#00B050"));text(canvas,"REUNIÓN SUSPENDIDA / ASAMBLEA",396,y+rowH*.7f,Math.min(11,rowH*.6f),Color.WHITE,true,Paint.Align.CENTER);y+=rowH;continue;}if(entry.getValue().isEmpty()){row(canvas,y,rowH,null,null);y+=rowH;}else for(Models.LifePart part:entry.getValue()){row(canvas,y,rowH,part,assigned.get(part.id));y+=rowH;}if(meeting.visit){serviceTalkRow(canvas,y,rowH,meeting);y+=rowH;}}
        pdf.finishPage(page);File file=output("Vida_Ministerio_"+month+".pdf");try(FileOutputStream out=new FileOutputStream(file)){pdf.writeTo(out);}pdf.close();return file;
    }

    File weeklyPdf(String date)throws IOException{
        LocalDate.parse(date);List<Models.LifePart> parts=db.lifeParts(date.substring(0,7));parts.removeIf(p->!date.equals(p.date));Models.Meeting meeting=db.meeting(date);if(parts.isEmpty()&&!meeting.visit)throw new IllegalArgumentException("No hay asignaciones capturadas para la semana seleccionada.");Map<Long,Models.LifeProgramRow> assigned=assigned(date.substring(0,7));PdfDocument pdf=new PdfDocument();PdfDocument.Page page=pdf.startPage(new PdfDocument.PageInfo.Builder(612,792,1).create());Canvas canvas=page.getCanvas();canvas.drawColor(Color.WHITE);float left=18,right=594,y=20;box(canvas,left,y,right-left,38,color("title","#00B050"));text(canvas,"PROGRAMA SEMANAL VIDA Y MINISTERIO",306,y+25,15,Color.WHITE,true,Paint.Align.CENTER);y+=38;Models.President president=db.president(meeting.presidentId);box(canvas,left,y,right-left,32,color("date","#0D6EFD"));fit(canvas,humanDate(date)+(president==null?"":" · Presidente: "+president.name),306,y+21,right-left-12,10.5f,Color.WHITE,true);y+=38;float[] x={left,left+56,left+178,left+334,left+456,right};String[] labels={"NÚM. / TIEMPO","ASIGNACIÓN","PARTICIPANTE","LECTOR","TEMA"};for(int i=0;i<labels.length;i++){box(canvas,x[i],y,x[i+1]-x[i],34,i==4?color("source","#955FEF"):i==2?color("main","#ED7D31"):i==3?color("aux","#FFC000"):color("assignment","#BFBFBF"));cell(canvas,labels[i],x[i],y,x[i+1]-x[i],34,7.4f,i==4?Color.WHITE:Color.BLACK,true,2);}y+=34;float rowH=Math.min(92f,(772-y)/Math.max(1,parts.size()+(meeting.visit?1:0)));for(Models.LifePart part:parts){Models.LifeProgramRow value=assigned.get(part.id);for(int i=0;i<labels.length;i++)box(canvas,x[i],y,x[i+1]-x[i],rowH,Color.rgb(248,248,248));cell(canvas,part.number+" · "+part.minutes+" min.",x[0],y,x[1]-x[0],rowH,7.7f,Color.BLACK,true,3);cell(canvas,part.assignmentName,x[1],y,x[2]-x[1],rowH,8.2f,Color.BLACK,true,4);cell(canvas,value==null||value.student==null?"PENDIENTE":value.student.name.toUpperCase(ES),x[2],y,x[3]-x[2],rowH,8.1f,Color.BLACK,true,4);cell(canvas,part.isBookStudy()?(value==null||value.reader==null?"PENDIENTE":value.reader.name.toUpperCase(ES)):"NO APLICA",x[3],y,x[4]-x[3],rowH,8.1f,Color.BLACK,true,4);cell(canvas,part.topic,x[4],y,x[5]-x[4],rowH,7.6f,Color.BLACK,false,7);y+=rowH;}if(meeting.visit)weeklyServiceTalkRow(canvas,y,rowH,meeting,x);
        pdf.finishPage(page);File file=output("Vida_Ministerio_semanal_"+date+".pdf");try(FileOutputStream out=new FileOutputStream(file)){pdf.writeTo(out);}pdf.close();return file;
    }

    File assignmentPdf(String month)throws IOException{List<CardEntry> cards=new ArrayList<>();for(Models.LifeProgramRow row:db.lifeProgram(month)){cards.add(new CardEntry(row,false));if(row.reader!=null)cards.add(new CardEntry(row,true));}if(cards.isEmpty())throw new IllegalArgumentException("No hay participantes asignados en el mes seleccionado.");PdfDocument pdf=new PdfDocument();int pageNumber=0;for(int offset=0;offset<cards.size();offset+=4){PdfDocument.Page page=pdf.startPage(new PdfDocument.PageInfo.Builder(612,792,++pageNumber).create());Canvas canvas=page.getCanvas();canvas.drawColor(Color.WHITE);paint.setColor(Color.GRAY);paint.setStrokeWidth(.8f);canvas.drawLine(306,0,306,792,paint);canvas.drawLine(0,396,612,396,paint);for(int i=0;i<4;i++){int index=offset+i;if(index<cards.size())drawCard(canvas,(i%2)*306+16,(i/2)*396+18,274,360,cards.get(index),1f);}pdf.finishPage(page);}File file=output("Asignaciones_Vida_Ministerio_"+month+".pdf");try(FileOutputStream out=new FileOutputStream(file)){pdf.writeTo(out);}pdf.close();return file;}

    File assignmentJpg(Models.LifeProgramRow row,boolean reader)throws IOException{CardEntry entry=new CardEntry(row,reader);Bitmap bitmap=Bitmap.createBitmap(1000,1400,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(Color.WHITE);drawCard(canvas,35,35,930,1330,entry,3.35f);File file=output("Vida_Ministerio_"+row.part.date+"_"+entry.person().name+".jpg");try(FileOutputStream out=new FileOutputStream(file)){bitmap.compress(Bitmap.CompressFormat.JPEG,94,out);}bitmap.recycle();return file;}

    private Map<Long,Models.LifeProgramRow> assigned(String month){Map<Long,Models.LifeProgramRow> result=new LinkedHashMap<>();for(Models.LifeProgramRow row:db.lifeProgram(month))result.put(row.part.id,row);return result;}
    private void serviceTalkRow(Canvas canvas,float y,float height,Models.Meeting meeting){float[] x={0,48,190,400,550,792};for(int i=0;i<x.length-1;i++)box(canvas,x[i],y,x[i+1]-x[i],height,Color.rgb(235,245,255));float size=Math.max(5.2f,Math.min(7.2f,height*.3f));cell(canvas,"VISITA",x[0],y,x[1]-x[0],height,size,Color.BLACK,true,2);cell(canvas,"Discurso de servicio · Canción: "+meeting.serviceSong,x[1],y,x[2]-x[1],height,size,Color.BLACK,true,3);cell(canvas,meeting.circuitOverseer,x[2],y,x[3]-x[2],height,size,Color.BLACK,true,3);cell(canvas,"SUPERINTENDENTE",x[3],y,x[4]-x[3],height,size,Color.BLACK,true,2);cell(canvas,meeting.serviceTalkTopic,x[4],y,x[5]-x[4],height,size,Color.BLACK,false,4);}
    private void weeklyServiceTalkRow(Canvas canvas,float y,float height,Models.Meeting meeting,float[] x){for(int i=0;i<x.length-1;i++)box(canvas,x[i],y,x[i+1]-x[i],height,Color.rgb(235,245,255));cell(canvas,"VISITA",x[0],y,x[1]-x[0],height,8f,Color.BLACK,true,2);cell(canvas,"Discurso de servicio\nCanción: "+meeting.serviceSong,x[1],y,x[2]-x[1],height,8f,Color.BLACK,true,4);cell(canvas,meeting.circuitOverseer,x[2],y,x[3]-x[2],height,8f,Color.BLACK,true,4);cell(canvas,"SUPERINTENDENTE",x[3],y,x[4]-x[3],height,7f,Color.BLACK,true,2);cell(canvas,meeting.serviceTalkTopic,x[4],y,x[5]-x[4],height,7.6f,Color.BLACK,false,7);}
    private void headers(Canvas c,float y,float h){float[] x={0,48,190,400,550,792};String[] labels={"NÚM. / TIEMPO","ASIGNACIÓN","PARTICIPANTE","LECTOR","TEMA"};for(int i=0;i<labels.length;i++){int fill=i==2?color("main","#ED7D31"):i==3?color("aux","#FFC000"):i==4?color("source","#955FEF"):color("assignment","#BFBFBF");box(c,x[i],y,x[i+1]-x[i],h,fill);cell(c,labels[i],x[i],y,x[i+1]-x[i],h,Math.min(8,h*.48f),i==4?Color.WHITE:Color.BLACK,true,2);}}
    private void row(Canvas c,float y,float h,Models.LifePart part,Models.LifeProgramRow assigned){float[] x={0,48,190,400,550,792};for(int i=0;i<x.length-1;i++)box(c,x[i],y,x[i+1]-x[i],h,Color.rgb(248,248,248));if(part==null){cell(c,"SIN PROGRAMA CAPTURADO",0,y,792,h,8,Color.GRAY,true,2);return;}cell(c,part.number+" · "+part.minutes+" min.",x[0],y,x[1]-x[0],h,Math.max(5.2f,Math.min(7.2f,h*.31f)),Color.BLACK,true,2);cell(c,part.assignmentName,x[1],y,x[2]-x[1],h,Math.max(5.3f,Math.min(7.4f,h*.31f)),Color.BLACK,true,3);cell(c,assigned==null||assigned.student==null?"PENDIENTE":assigned.student.name.toUpperCase(ES),x[2],y,x[3]-x[2],h,Math.max(5.2f,Math.min(7.2f,h*.3f)),Color.BLACK,true,3);cell(c,part.isBookStudy()?(assigned==null||assigned.reader==null?"PENDIENTE":assigned.reader.name.toUpperCase(ES)):"—",x[3],y,x[4]-x[3],h,Math.max(5.2f,Math.min(7.2f,h*.3f)),Color.BLACK,true,3);cell(c,part.topic,x[4],y,x[5]-x[4],h,Math.max(5f,Math.min(6.7f,h*.27f)),Color.BLACK,false,4);}
    private void drawCard(Canvas c,float left,float top,float width,float height,CardEntry entry,float scale){paint.setStyle(Paint.Style.STROKE);paint.setColor(Color.GRAY);paint.setStrokeWidth(.7f*scale);c.drawRect(left,top,left+width,top+height,paint);paint.setStyle(Paint.Style.FILL);float x=left+11*scale,y=top+22*scale;text(c,"ASIGNACIÓN VIDA Y MINISTERIO",x,y,10.5f*scale,Color.DKGRAY,true,Paint.Align.LEFT);y+=22*scale;field(c,"Nombre:",entry.person().name,x,y,width-22*scale,scale);y+=20*scale;field(c,"Fecha:",humanDate(entry.row.part.date),x,y,width-22*scale,scale);y+=20*scale;field(c,"Función:",entry.reader?"Lector del Estudio del Libro":entry.row.part.isBookStudy()?"Conductor":"Participante",x,y,width-22*scale,scale);y+=20*scale;field(c,"Asignación:",entry.row.part.number+". "+entry.row.part.assignmentName,x,y,width-22*scale,scale);y+=27*scale;text(c,"Tiempo asignado: "+entry.row.part.minutes+" minutos",x,y,8*scale,Color.DKGRAY,true,Paint.Align.LEFT);y+=20*scale;text(c,"Tema:",x,y,8*scale,Color.DKGRAY,true,Paint.Align.LEFT);drawWrapped(c,entry.row.part.topic,x,y+10*scale,width-22*scale,7.2f*scale,Color.DKGRAY,7);Models.President president=entry.row.president;float bottom=top+height-62*scale;text(c,"Sala Principal",x,bottom,8.2f*scale,Color.DKGRAY,true,Paint.Align.LEFT);text(c,"Presidente: "+(president==null?"Pendiente":president.name),x,bottom+17*scale,7.2f*scale,Color.DKGRAY,false,Paint.Align.LEFT);text(c,"Si no podrá participar, comuníquese con el presidente.",x,bottom+34*scale,6.5f*scale,Color.GRAY,false,Paint.Align.LEFT);}
    private void field(Canvas c,String label,String value,float x,float y,float width,float scale){text(c,label,x,y,8.3f*scale,Color.DKGRAY,true,Paint.Align.LEFT);float start=paint.measureText(label)+3*scale;paint.setColor(Color.LTGRAY);paint.setStrokeWidth(.4f*scale);c.drawLine(x+start,y+2*scale,x+width,y+2*scale,paint);fit(c,value,x+start+(width-start)/2,y-1*scale,width-start-2*scale,6.7f*scale,Color.BLACK,false);}
    private String humanDate(String iso){try{LocalDate date=LocalDate.parse(iso);String day=date.getDayOfWeek().getDisplayName(TextStyle.FULL,ES),month=date.getMonth().getDisplayName(TextStyle.FULL,ES);return day+", "+date.getDayOfMonth()+" de "+month+" de "+date.getYear();}catch(Exception ignored){return iso;}}
    private void box(Canvas c,float x,float y,float w,float h,int fill){paint.setStyle(Paint.Style.FILL);paint.setColor(fill);c.drawRect(x,y,x+w,y+h,paint);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(.7f);paint.setColor(Color.BLACK);c.drawRect(x,y,x+w,y+h,paint);paint.setStyle(Paint.Style.FILL);}
    private void text(Canvas c,String value,float x,float y,float size,int color,boolean bold,Paint.Align align){paint.setTextSize(size);paint.setColor(color);paint.setTypeface(Typeface.create(Typeface.SANS_SERIF,bold?Typeface.BOLD:Typeface.NORMAL));paint.setTextAlign(align);paint.setStyle(Paint.Style.FILL);c.drawText(value==null?"":value,x,y,paint);}
    private void fit(Canvas c,String value,float center,float y,float maxWidth,float size,int color,boolean bold){String text=value==null?"":value;text(c,"",center,y,size,color,bold,Paint.Align.CENTER);if(paint.measureText(text)>maxWidth){while(text.length()>1&&paint.measureText(text+"…")>maxWidth)text=text.substring(0,text.length()-1);text+="…";}c.drawText(text,center,y,paint);}
    private void cell(Canvas c,String value,float left,float top,float width,float height,float size,int color,boolean bold,int requestedLines){int saved=c.save();c.clipRect(left+1,top+1,left+width-1,top+height-1);text(c,"",left+width/2,top,size,color,bold,Paint.Align.CENTER);Paint.FontMetrics metrics=paint.getFontMetrics();float lineHeight=(metrics.descent-metrics.ascent)*1.04f;int maxLines=Math.max(1,Math.min(requestedLines,(int)((height-2)/Math.max(1,lineHeight))));List<String> lines=wrap(value,width-6,maxLines);float first=top+(height-lines.size()*lineHeight)/2-metrics.ascent;for(int i=0;i<lines.size();i++)c.drawText(lines.get(i),left+width/2,first+i*lineHeight,paint);c.restoreToCount(saved);}
    private List<String> wrap(String value,float width,int maxLines){String clean=value==null?"":value.trim().replaceAll("\\s+"," ");List<String> all=new ArrayList<>();if(clean.isEmpty()){all.add("");return all;}String line="";for(String word:clean.split(" ")){String next=line.isEmpty()?word:line+" "+word;if(!line.isEmpty()&&paint.measureText(next)>width){all.add(line);line=word;}else line=next;}if(!line.isEmpty())all.add(line);boolean truncated=all.size()>maxLines;List<String> result=new ArrayList<>(all.subList(0,Math.min(maxLines,all.size())));if(truncated){int last=result.size()-1;String text=result.get(last);while(text.length()>1&&paint.measureText(text+"…")>width)text=text.substring(0,text.length()-1);result.set(last,text+"…");}return result;}
    private void drawWrapped(Canvas c,String value,float x,float y,float width,float size,int color,int maxLines){text(c,"",x,y,size,color,false,Paint.Align.LEFT);String line="";int lines=0;for(String word:(value==null?"":value).split(" ")){String next=line.isEmpty()?word:line+" "+word;if(!line.isEmpty()&&paint.measureText(next)>width){c.drawText(line,x,y+lines*size*1.18f,paint);if(++lines>=maxLines)return;line=word;}else line=next;}if(lines<maxLines)c.drawText(line,x,y+lines*size*1.18f,paint);}
    private static final class CardEntry{final Models.LifeProgramRow row;final boolean reader;CardEntry(Models.LifeProgramRow row,boolean reader){this.row=row;this.reader=reader;}Models.Student person(){return reader?row.reader:row.student;}}
}
